{
  "title": "Build a Campfire",
  "steps": [
    {
      "instruction": "Clear a circle of bare earth and ring it with stones.",
      "companion": {"type": "zone", "shape": "circle", "size_m": 1.2, "stage": null},
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Gather all three fuel grades before you strike a spark.",
      "companion": {"type": "checklist", "items": ["Dry tinder", "Thin kindling", "Thick fuel wood"], "stage": null},
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Lay a loose nest of tinder in the centre of the pit.",
      "companion": {"type": "hologram_stage", "stage": 2},
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Stack the kindling log-cabin style around the tinder core.",
      "companion": {"type": "hologram_stage", "stage": 3},
      "safety": false,
      "warning": null
    },
    {
      "instruction": "Light the tinder from the upwind side, then step back.",
      "companion": {"type": "compass", "label": "Check wind", "stage": null},
      "safety": true,
      "warning": "Never light a fire in strong wind or under low branches."
    },
    {
      "instruction": "Feed thicker wood once the flames hold steady.",
      "companion": {"type": "hologram_stage", "stage": 4},
      "safety": false,
      "warning": null
    }
  ]
}
